'use strict';
const D=window.FG_DATA, $=s=>document.querySelector(s), E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=2)=>v===null||v===undefined?'unavailable':Number(v).toLocaleString('en-GB',{maximumFractionDigits:d});
const clock=s=>new Date(Date.parse(D.start)+s*1000).toISOString().slice(11,19)+' UTC';
const signalName=s=>s.replaceAll('_',' ');
const badge=(s,k='')=>`<span class="badge ${k}">${E(s)}</span>`;
const head=(n,title,subtitle)=>`<div class="page-header"><div class="eyebrow">${n} / FLEETGUARD ENGINEERING ATLAS</div><h1>${title}</h1><p>${subtitle}</p></div>`;
const sources=(...paths)=>`<div class="source-links">${paths.map(p=>`<button data-source="${p}">${E(p.split('/').slice(-2).join('/'))} ↗</button>`).join('')}</div>`;
const note=(title,text,w=false)=>`<div class="note ${w?'warning':''}"><strong>${title}</strong><p>${text}</p></div>`;
const panel=(title,body,tag='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${tag}</div>${body}</section>`;
let teardown=()=>{}, currentPage='', systemLevel='wagon', exploded=false, modalReturn=null, selectedPart=null;
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const componentInfo={
 wagon:{title:'One connected wagon.',count:'1 wagon',text:'One report combines wagon context with readings from both bogies, all four axles and all eight wheels.',signals:['speed_kph','latitude / longitude','ambient_temp_c','three acceleration axes','rail_condition','estimated_adhesion_coefficient','BPP / AR / SR'],path:'src/fleetguard/contracts/models.py'},
 bogie:{title:'Two bogies. Two BCP readings.',count:'2 bogies',text:'Each bogie carries two axles and one brake-cylinder pressure measurement. Exactly one bogie is handbrake-equipped in the asset metadata.',signals:['bogie_id: 1 / 2','handbrake_equipped','brake_cylinder_pressure_bar'],path:'src/fleetguard/generator/normalise.py'},
 axle:{title:'Four axles. Four shared rotations.',count:'4 axles / wheelsets',text:'An axle joins left and right wheels. Wheel speed and RPM belong to that shared rotation; vibration and load are reported at axle level. Inner is towards the wagon centre; outer is towards its nearest end.',signals:['axle_position: inner / outer','wheel_speed_kph','rotational_speed_rpm','axle_load_tonnes','vibration_rms_g'],path:'src/fleetguard/contracts/models.py'},
 wheel:{title:'Eight wheels. Eight bearing observations.',count:'8 wheels',text:'Each axle has a left and right wheel. Bearing temperature is retained for each side. Diameter is fixed wheel metadata, used in the generator’s speed-to-RPM calculation.',signals:['wheel_side: left / right','bearing_temp_c','diameter_mm (metadata)'],path:'src/fleetguard/generator/healthy.py'},
 battery:{title:'One shared wagon battery.',count:'1 battery',text:'At simulated speed below 5 km/h the controller uses battery power. In generator mode the simplified battery charges. Healthy standby capacity varies between five and seven days; the journey fixture is not an endurance study.',signals:['battery_voltage_v: 3.0–4.2 V simulation scale','power_source','available_axle_generators','battery_standby_days (metadata)'],path:'src/fleetguard/generator/healthy.py'},
 controller:{title:'The controller makes the wagon observable.',count:'1 controller',text:'A distinct regulated supply rail powers the reporting controller. Controller temperature, health and counters are reported alongside the mechanical telemetry. An outage removes the whole event, not just one value.',signals:['temperature_c','supply_voltage_v','health_status','uptime_seconds','reset_count','sensor_communication_error_count'],path:'src/fleetguard/generator/extended_anomalies.py'},
 brakes:{title:'Shared pneumatics, local brake cylinders.',count:'3 shared + 2 BCP signals',text:'BPP, auxiliary reservoir and secondary reservoir are wagon-level readings. BCP is individual to each bogie. Brake demand is independent simulated command context, rather than inferred from the faulty pressure.',signals:['brake_pipe_pressure_bar','auxiliary_reservoir_pressure_bar','secondary_reservoir_pressure_bar','bogie 1 / 2 brake_cylinder_pressure_bar','brake_demand'],path:'src/fleetguard/generator/healthy.py'}
};
function wagonSVG(level='wagon',explode=false,fault=false,target=null){
 const match=(l,b,a,w)=>level===l&&(!target||(!target.bogie_id||target.bogie_id===b)&&(!target.axle_position||target.axle_position===a)&&(!target.wheel_side||target.wheel_side===w));
 const colours={wagon:'#536d7c',bogie:'#5477a0',axle:'#657a85',wheel:'#7766a0',generator:'#087c79',battery:'#ba882c',controller:'#087c79',brakes:'#347ba1'};
 const group=(l,b,a,w,shift=0)=>`data-component="${l}" data-shift="${shift}" data-bogie="${b||''}" data-axle="${a||''}" data-wheel="${w||''}" class="part ${match(l,b,a,w)?(fault?'faulted':'selected'):''}" style="color:${match(l,b,a,w)&&fault?'#ba4a3d':colours[l]}" transform="translate(0 ${explode?shift:0})"`;
 const text=(x,y,t,anchor='middle')=>`<text x="${x}" y="${y}" text-anchor="${anchor}" class="engineering-label">${t}</text>`;
 let out=`<svg viewBox="0 0 960 585" role="img" aria-label="Exploded side-view schematic: wagon, two bogies, four axles with left and right wheels below"><defs><pattern id="hatch" width="12" height="12" patternUnits="userSpaceOnUse"><path d="M0 12L12 0" stroke="#dbe3df" stroke-width=".7"/></pattern></defs>`;
 out+=`<path d="M45 490H915M45 498H915" stroke="#b4c2bb"/><g ${group('wagon',null,null,null,-12)}><path d="M110 46Q110 35 126 35H820Q842 35 842 57V190Q842 207 824 207H127Q110 207 110 190Z" fill="#f8faf6" stroke="currentColor" stroke-width="2.5"/><path d="M184 50L164 195M289 50L274 195M394 50L384 195M499 50L495 195M604 50L612 195M709 50L731 195" stroke="#bcc9c5"/><path d="M90 222V210H866V222M110 225H846M184 210V233M333 210V233M616 210V233M765 210V233" fill="none" stroke="#849b9c" stroke-width="1.7"/><path d="M90 216H55M866 216H905" stroke="#849b9c" stroke-width="2"/>${text(475,77,'FG-WGN-0001 · FREIGHT WAGON')}${text(475,97,'MOTION / LOCATION / ENVIRONMENT')}</g>`;
 // Shared pneumatic backbone, reservoirs and pressure transducer.
 out+=`<g ${group('brakes',null,null,null,-12)}><path d="M166 184H591M216 172V184M330 172V184M448 172V184" stroke="currentColor" stroke-width="2" fill="none"/>${[178,292,406].map((x,i)=>`<g data-inspect="${['bpp','ar','sr'][i]}" tabindex="0" role="button" aria-label="Inspect ${['brake pipe pressure','auxiliary reservoir','secondary reservoir'][i]}"><rect x="${x}" y="130" width="94" height="42" rx="14" fill="#edf5fa" stroke="currentColor" stroke-width="1.6"/><path d="M${x+11} 133V169M${x+83} 133V169" stroke="currentColor" opacity=".45"/>${text(x+47,157,['BPP','AR','SR'][i])}</g>`).join('')}</g>`;
 out+=`<g ${group('controller',null,null,null,-12)}><rect x="621" y="129" width="103" height="48" rx="5" fill="#e4f3ed" stroke="currentColor" stroke-width="2"/><rect x="632" y="138" width="32" height="18" rx="2" fill="white" stroke="currentColor"/><path d="M698 126V110M688 116Q698 96 708 116M682 108Q698 84 714 108" fill="none" stroke="currentColor"/>${text(674,169,'CONTROLLER')}<path d="M638 180v5m12-5v5m12-5v5m12-5v5m12-5v5" stroke="currentColor"/></g>`;
 out+=`<g ${group('battery',null,null,null,-12)}><rect x="757" y="132" width="63" height="44" rx="4" fill="#fff5db" stroke="currentColor" stroke-width="2"/><path d="M820 145h5v17h-5" fill="none" stroke="currentColor"/><path d="M770 147v15m-7-8h14m18 0h12" stroke="currentColor" stroke-width="2"/>${text(789,194,'BATTERY')}</g>`;
 for(const b of [1,2]){
  const bx=b===1?151:584;
  if(explode)out+=`<path d="M${bx+27} 220V452M${bx+176} 220V452" stroke="#b9c7c1" stroke-dasharray="3 5"/>`;
  out+=`<g ${group('bogie',b,null,null,72)}><path d="M${bx} 235Q${bx} 224 ${bx+12} 224H${bx+195}Q${bx+208} 224 ${bx+208} 237V263H${bx}Z" fill="#edf1f8" stroke="currentColor" stroke-width="2"/><path d="M${bx+18} 240H${bx+190}" stroke="currentColor"/>${text(bx+104,236,`BOGIE ${b} · ${b===1?'HB':'NHB'}`)}${[35,167].map(dx=>`<path d="M${bx+dx} 243l-8 4 16 4-16 4 16 4-8 4" fill="none" stroke="currentColor"/>`).join('')}</g>`;
  out+=`<g data-inspect="bcp" ${group('brakes',b,null,null,72)}><rect x="${bx+70}" y="245" width="68" height="20" rx="8" fill="#e8f3fa" stroke="currentColor"/><path d="M${bx+53} 255H${bx+70}M${bx+138} 255H${bx+157}" stroke="currentColor" stroke-width="3"/>${text(bx+104,259,'BCP '+b)}</g>`;
  for(const a of ['outer','inner']){
   const x=b===1?(a==='outer'?184:333):(a==='outer'?765:616);
   out+=`<g ${group('axle',b,a,null,122)}><path d="M${x-26} 270H${x+26}" stroke="currentColor" stroke-width="7"/><rect x="${x-11}" y="260" width="22" height="20" rx="4" fill="#e8eeee" stroke="currentColor"/></g>`;
   out+=`<g ${group('generator',b,a,null,93)}><rect x="${x-21}" y="230" width="42" height="27" rx="12" fill="#e4f3ed" stroke="currentColor" stroke-width="2"/><circle cx="${x}" cy="243" r="9" fill="white" stroke="currentColor"/><path d="M${x-6} 243h12M${x} 237v12M${x+21} 243h8" stroke="currentColor"/></g>`;
   for(const w of ['left','right']){
    const wx=x+(w==='left'?-29:29);
    out+=`<g ${group('wheel',b,a,w,166)}><circle cx="${wx}" cy="279" r="24" fill="#f2eef9" stroke="currentColor" stroke-width="2"/><circle cx="${wx}" cy="279" r="18" fill="none" stroke="currentColor" opacity=".4"/><g class="wheel-spokes" style="transform-origin:${wx}px 279px"><path d="M${wx-15} 279h30M${wx} 264v30" stroke="currentColor" opacity=".5"/></g><circle cx="${wx}" cy="279" r="6" fill="white" stroke="currentColor" stroke-width="2"/>${text(wx,315,w==='left'?'L':'R')}</g>`;
   }
  }
 }
 out+=`${identityRibbonSVG()}${text(45,575,'ILLUSTRATIVE SYSTEM · NOT TO SCALE','start')}${text(915,575,'2 BOGIES / 4 AXLES / 8 WHEELS','end')}</svg>`;return out;
}

function diagram(level='wagon',explode=false,fault=false,target=null){return `<div class="drawing" id="wagon-drawing">${wagonSVG(level,explode,fault,target)}</div>`;}
componentInfo.generator={title:'Four axle generators',count:'4 generators',text:'Rotation supplies the controller and charges the shared battery in the simulated moving state.',signals:['wheel_speed_kph / rotational_speed_rpm (axle)','available_axle_generators (wagon)','power_source (wagon)'],path:'src/fleetguard/generator/healthy.py'};
function systemDetails(level){const c=componentInfo[level];return `<div class="panel-body component-detail"><div class="kicker">${c.count.toUpperCase()}</div><h3>${c.title}</h3><div class="signal-list">${c.signals.map(s=>`<code>${E(readable(s))}</code>`).join('')}</div><p>${c.text}</p></div>`;}

function animateExplosion(open){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;document.querySelectorAll('#wagon-drawing [data-component]').forEach(el=>{const d=Number(el.dataset.shift);el.animate([{transform:`translateY(${open?0:d}px)`},{transform:`translateY(${open?d:0}px)`}],{duration:800,easing:'cubic-bezier(.2,.6,.3,1)'});});}


